-- B1 Seed: 58 Stellen aus der freigegebenen Buch-Landkarte (B-8, 2026-11-21)
-- Erzeugt von scripts/build-book-seed.mjs aus docs/buch/buch-landkarte-v1.md. Nicht von Hand ändern.
-- Spätere Änderungen: Landkarte ändern, Skript erneut laufen lassen, NEUE Migration anlegen.
-- Rückgängig machen: delete from public.book_passages;

on conflict (id) do update set
  kind = excluded.kind,
  position = excluded.position,
  part_title = excluded.part_title,
  season_label = excluded.season_label,
  title = excluded.title,
  situation_summary = excluded.situation_summary,
  key_quote = excluded.key_quote,
  bridge_question = excluded.bridge_question,
  fits_when = excluded.fits_when,
  book_questions = excluded.book_questions,
  pattern_keys = excluded.pattern_keys,
  mechanisms = excluded.mechanisms,
  themes = excluded.themes,
  coach_note = excluded.coach_note,
  is_resolution = excluded.is_resolution,
  is_sensitive = excluded.is_sensitive,
  sensitive_rule = excluded.sensitive_rule,
  is_active = excluded.is_active,
  approved_by_jerome_at = excluded.approved_by_jerome_at,
  updated_at = now();
