values
  ($bp$V-1$bp$, $bp$jerome$bp$, 0, $bp$Vorweg$bp$, null, $bp$Mehr Einfluss, als du glaubst$bp$, $bp$Im Prolog erzählt Jerome, wie er Ratgeber gekauft hat, „als gäb's dafür Treuepunkte", und trotzdem derselbe blieb. Nicken ist noch nicht Anders-Machen.$bp$, $bp$Du hast mehr Einfluss, als du glaubst.$bp$, $bp$„Jerome schreibt im Prolog von dem einen Satz, den du mitnehmen sollst. Weißt du noch, welcher das war?"$bp$, $bp$der Nutzer sich als machtlos erlebt oder sagt „Ich weiß das ja alles, ändert aber nichts"$bp$, '{}'::text[], '{}'::text[], array[$bp$einfluss$bp$]::text[], array[$bp$Veränderung$bp$, $bp$Ohnmacht$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$V-2$bp$, $bp$jerome$bp$, 0, $bp$Vorweg$bp$, null, $bp$Einfach ist nicht gleich leicht$bp$, $bp$Jerome hat zehn Jahre gebraucht, um die Theorie in die Praxis zu bringen. Ein Satz einer Therapeutin begleitet ihn seitdem.$bp$, $bp$Einfach ist nicht gleich leicht.$bp$, $bp$„Was ist an dem, was du gerade vorhast, einfach und trotzdem nicht leicht?"$bp$, $bp$der Nutzer frustriert ist, dass er etwas verstanden hat und es trotzdem nicht umsetzt$bp$, '{}'::text[], '{}'::text[], array[$bp$autobahn_trampelpfad$bp$]::text[], array[$bp$Geduld$bp$, $bp$Frust über sich selbst$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T1-D1$bp$, $bp$dialog$bp$, 1, $bp$Was hast du gehört?$bp$, $bp$Herbst$bp$, $bp$Kerstin isst Pizza$bp$, $bp$Tims Chef kommentiert die Präsentation vor allen mit „Das hätten wir auch einfacher haben können". Tim kocht. Kerstin, die die Präsentation mitgebaut hat, geht entspannt Pizza essen.$bp$, $bp$Gleicher Chef, gleicher Satz, gleiches Meeting. Sie isst Pizza, du willst ihn erschlagen.$bp$, $bp$„Erinnert dich das an Tim und Kerstin im ersten Gespräch?" Danach: „Was hast du in dem Satz gehört?"$bp$, $bp$der Nutzer sich über eine Bemerkung ärgert und andere, die dabei waren, ruhig geblieben sind$bp$, '{}'::text[], '{}'::text[], array[$bp$gesagt_ist_nicht_gehoert$bp$, $bp$gedankenlesen$bp$]::text[], array[$bp$Arbeit$bp$, $bp$Kritik$bp$, $bp$Chef$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T1-D2$bp$, $bp$dialog$bp$, 1, $bp$Was hast du gehört?$bp$, $bp$Herbst$bp$, $bp$Die Fernbedienung$bp$, $bp$Tim ist überzeugt, dass sein Chef an seiner Laune schuld ist. Mara spielt das zu Ende: Wer entscheidet dann über Tims Tag?$bp$, $bp$Dann gibst du die Fernbedienung für deine Laune einem Typen, den du für ein Arschloch hältst.$bp$, $bp$„Wer hat gerade die Fernbedienung für deine Laune?"$bp$, $bp$der Nutzer seine Stimmung vollständig einer anderen Person zuschreibt$bp$, '{}'::text[], '{}'::text[], array[$bp$fernbedienung$bp$]::text[], array[$bp$Arbeit$bp$, $bp$Schuld$bp$, $bp$Laune$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T1-D3$bp$, $bp$dialog$bp$, 1, $bp$Was hast du gehört?$bp$, $bp$Herbst$bp$, $bp$Beteiligt, nicht schuld$bp$, $bp$Tim wehrt ab: „Also doch selbst schuld." Mara trennt Schuld von Beteiligung. Der Satz kam vom Chef, was daraus wurde, liegt bei Tim. Am Ende gibt Tim zu, dass Kerstin etwas anderes gehört hat.$bp$, $bp$Aber was aus dem Satz geworden ist, nachdem er bei dir angekommen ist – das ist nicht mehr die Sache von deinem Chef. Das ist deine.$bp$, $bp$„Tim hat an der Stelle auch erst ‚Also doch selbst schuld' gesagt. Wie hört sich das für dich an: beteiligt statt schuld?"$bp$, $bp$der Nutzer Verantwortung als Vorwurf hört („Dann bin ich jetzt wohl schuld")$bp$, '{}'::text[], '{}'::text[], array[$bp$fernbedienung$bp$, $bp$beteiligt_statt_schuld$bp$]::text[], array[$bp$Verantwortung$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T1-E$bp$, $bp$erklaerung$bp$, 1, $bp$Was hast du gehört?$bp$, $bp$Herbst$bp$, $bp$Was dahintersteckt: Gesagt ist nicht gehört$bp$, $bp$Zwischen Gesagtem und Gehörtem sitzt ein Übersetzer, und das bist du. Die vier Seiten einer Nachricht nach Schulz von Thun: Wer unsicher ist, hört mit dem Beziehungsohr. Dazu Epiktet. Die eigene Version fühlt sich an wie die Wirklichkeit. Beteiligt, nicht schuld.$bp$, $bp$Schuld lähmt. Verantwortung macht wieder handlungsfähig.$bp$, null, null, array[$bp$Was hast du gehört? Und was wurde tatsächlich gesagt?$bp$, $bp$Wenn du dir die Fernbedienung ein Stück zurückholen wolltest: Wo würdest du anfangen?$bp$]::text[], '{}'::text[], array[$bp$gesagt_ist_nicht_gehoert$bp$, $bp$beteiligt_statt_schuld$bp$]::text[], '{}'::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T1-J$bp$, $bp$jerome$bp$, 1, $bp$Was hast du gehört?$bp$, $bp$Herbst$bp$, $bp$Ich war Tim$bp$, $bp$Jerome hatte die Coaching-Ausbildung schon abgeschlossen und reagierte trotzdem genau wie Tim auf seinen Chef. Er sammelte jeden Tag Beweise und hat „jeden Morgen vorsorglich frische Batterien reingemacht".$bp$, $bp$Verstehen schützt dich nicht davor, reinzufallen. Es sorgt dafür, dass du nicht drinbleibst.$bp$, $bp$„Jerome schreibt, dass ihn sein ganzes Wissen nicht davor bewahrt hat, reinzufallen. Was hat dir geholfen, dass du nicht drinbleibst?"$bp$, $bp$der Nutzer sich schämt, weil er „es doch besser wissen müsste"$bp$, '{}'::text[], '{}'::text[], array[$bp$fernbedienung$bp$, $bp$rueckfall_merken$bp$]::text[], array[$bp$Arbeit$bp$, $bp$Chef$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T2-D1$bp$, $bp$dialog$bp$, 2, $bp$Tausend kleine Tiger$bp$, $bp$November$bp$, $bp$Der Kombi am Zebrastreifen$bp$, $bp$Ein Kombi rauscht über den Zebrastreifen, Tim und Mara springen zur Seite. Tim „weiß", dass der Fahrer am Handy hing und es ihm egal war, gesehen hat er nichts davon. Mara hat dieselbe Regel im Kopf und eine andere Geschichte.$bp$, $bp$Mein Kopf hat sich ’ne andere Geschichte ausgesucht als deiner. Das ist alles.$bp$, $bp$„Kennst du die Szene mit dem Kombi? Welche andere Geschichte könnte dein Kopf sich hier aussuchen?"$bp$, $bp$der Nutzer einer fremden Person sicher eine Absicht unterstellt$bp$, '{}'::text[], '{}'::text[], array[$bp$wertesystem_kette$bp$, $bp$automatische_gedanken$bp$, $bp$gedankenlesen$bp$]::text[], array[$bp$Alltag$bp$, $bp$Wut$bp$, $bp$Unterstellung$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T2-D2$bp$, $bp$dialog$bp$, 2, $bp$Tausend kleine Tiger$bp$, $bp$November$bp$, $bp$Der Tiger ist längst weg$bp$, $bp$Mara erklärt, warum Bewerten überlebenswichtig ist: Wer beim Tiger erst nachdenkt, wird nicht unser Vorfahr. Nur ist der Kombi-Tiger längst beim Abendbrot, und Tim läuft mit den Schultern an den Ohren herum.$bp$, $bp$Und du sitzt immer noch auf dem Baum.$bp$, $bp$„Ist dein Tiger noch da, oder sitzt du noch auf dem Baum?"$bp$, $bp$der Nutzer an einem längst vergangenen Ärger festhält$bp$, '{}'::text[], '{}'::text[], array[$bp$automatische_gedanken$bp$, $bp$nicht_nicht_bewerten$bp$]::text[], array[$bp$Ärger$bp$, $bp$der nachhängt$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T2-D3$bp$, $bp$dialog$bp$, 2, $bp$Tausend kleine Tiger$bp$, $bp$November$bp$, $bp$Ich find die Beweise, weil ich sie suche$bp$, $bp$Tim zählt auf, was sein Chef alles falsch macht. Das Hallo, das er selbst nicht mehr sagt, und das Lob, das er Kerstin zuschreibt, kommen darin nicht vor. Dazu 22 Videos über toxische Chefs. Tim merkt, dass er sich selbst etwas verkauft, so wie er im Job Proteinriegel verkauft.$bp$, $bp$Ich find die Beweise, weil ich sie suche.$bp$, $bp$„Tim hat seinem Chef kein Hallo mehr gesagt, weil der ihm auch keins sagt. Gibt es bei dir so etwas, das du nicht mehr tust, weil der andere es nicht tut?"$bp$, $bp$der Nutzer eine Liste von Belegen gegen jemanden vorträgt, oder wenn er sich zurückzieht, weil „der andere ja auch nicht …"$bp$, '{}'::text[], array[$bp$rueckzug_unter_druck$bp$]::text[], array[$bp$bestaetigungsfehler$bp$, $bp$selbsterfuellende_prophezeiung$bp$, $bp$zirkulaere_kausalitaet$bp$]::text[], array[$bp$Arbeit$bp$, $bp$Chef$bp$, $bp$Social Media$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T2-E$bp$, $bp$erklaerung$bp$, 2, $bp$Tausend kleine Tiger$bp$, $bp$November$bp$, $bp$Was dahintersteckt: Das Wertesystem$bp$, $bp$Das Wertesystem als inneres Betriebssystem. Die Kette, der Kern des Buches: Wahrnehmung → Wertesystem → Bewertung → Gefühl → beeinflusst die nächste Wahrnehmung. Automatische Gedanken nach Beck. „Wir können nicht nicht bewerten." Die Krallen machen wir selbst dran. Ärger ist ein Wegweiser zu den eigenen Werten. Darunter liegen Bedürfnisse: Sicherheit, dazugehören, sich wertvoll fühlen, selbst bestimmen. Dazu die selbsterfüllende Prophezeiung.$bp$, $bp$Die Bewertung kannst du nicht abstellen. Was du danach damit machst, darauf hast du Einfluss.$bp$, null, null, array[$bp$Was ging dir durch den Kopf, bevor das Gefühl da war?$bp$, $bp$Welche Geschichte könnte der andere in dem Moment im Kopf gehabt haben?$bp$]::text[], '{}'::text[], array[$bp$wertesystem_kette$bp$, $bp$automatische_gedanken$bp$, $bp$beduerfnisse$bp$, $bp$selbsterfuellende_prophezeiung$bp$]::text[], '{}'::text[], $bp$Die Kette entspricht dem „Brille"-Modell der App (Wahrnehmung, Bewertung, Gedanke, Gefühl). Wer das Buch kennt, kennt das Modell schon.$bp$, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T2-J$bp$, $bp$jerome$bp$, 2, $bp$Tausend kleine Tiger$bp$, $bp$November$bp$, $bp$Die SMS$bp$, $bp$Jerome bekam Bauchschmerzen bei einer SMS eines Kumpels, die er noch gar nicht geöffnet hatte. Er war überzeugt, für die Stimmung der anderen verantwortlich zu sein.$bp$, $bp$Ich saß schon auf dem Baum, bevor der Tiger überhaupt aus dem Gebüsch war.$bp$, $bp$„Jerome erzählt im Buch von einer SMS, die ihm Bauchschmerzen gemacht hat, bevor er sie überhaupt gelesen hatte. Kennst du das?"$bp$, $bp$der Nutzer schon vor einem Gespräch oder einer Nachricht mit dem Schlimmsten rechnet$bp$, '{}'::text[], array[$bp$uebernahme_reflex$bp$]::text[], array[$bp$automatische_gedanken$bp$, $bp$glaubenssatz$bp$]::text[], array[$bp$Freundschaft$bp$, $bp$Kritik$bp$, $bp$Angst vor Ärger$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T3-D1$bp$, $bp$dialog$bp$, 3, $bp$Die Kampagne$bp$, $bp$erster Frost$bp$, $bp$Die Tabelle$bp$, $bp$Jule erzählt, dass sie im Job unglücklich ist. Tim baut noch am selben Abend bis halb zwei eine Bewerbungs-Kampagne: 14 Firmen, Lebenslauf, Ampel-Tabelle. Jule rührt sie nicht an. An einem miesen Tag platzt es aus Tim heraus: Er mache alles für sie, und sie merke nicht mal, wenn es ihm schlecht geht.$bp$, $bp$Ich hab dich um die Tabelle nicht gebeten.$bp$, $bp$„Erinnert dich das an Tims Tabelle für Jule?"$bp$, $bp$der Nutzer enttäuscht ist, dass seine Hilfe nicht angenommen oder nicht gewürdigt wird$bp$, '{}'::text[], array[$bp$uebernahme_reflex$bp$, $bp$harmonie_um_jeden_preis$bp$]::text[], array[$bp$ungefragte_hilfe$bp$, $bp$unausgesprochene_erwartungen$bp$, $bp$gedankenlesen$bp$]::text[], array[$bp$Partnerschaft$bp$, $bp$Helfen$bp$, $bp$Enttäuschung$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T3-D2$bp$, $bp$dialog$bp$, 3, $bp$Die Kampagne$bp$, $bp$erster Frost$bp$, $bp$Was könnte angekommen sein?$bp$, $bp$Mara dreht die Frage aus Teil 1 um: Was ist bei Jule angekommen? Über die Umkehrung (Basti schickt Tim ungefragt 14 Stellenanzeigen) versteht Tim es. Trotzdem juckt es ihm in den Fingern, die zwei neuen Stellen einzutragen.$bp$, $bp$Ich wollte helfen. Und angekommen ist vielleicht: Ich trau’s dir nicht zu.$bp$, $bp$„Wie wäre es für dich, wenn jemand dir genau so geholfen hätte?"$bp$, $bp$der Nutzer gut gemeint geholfen hat und Ablehnung erntet$bp$, '{}'::text[], array[$bp$uebernahme_reflex$bp$]::text[], array[$bp$gesagt_ist_nicht_gehoert$bp$, $bp$ungefragte_hilfe$bp$, $bp$autobahn_trampelpfad$bp$]::text[], array[$bp$Partnerschaft$bp$, $bp$Helfen$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T3-D3$bp$, $bp$dialog$bp$, 3, $bp$Die Kampagne$bp$, $bp$erster Frost$bp$, $bp$Beide warten auf den ersten Schritt$bp$, $bp$Seit dem Streit reden Tim und Jule nur das Nötigste. Tim erkennt die Parallele zum Chef. Beide hätten etwas sagen können, keiner hat es getan.$bp$, $bp$Klingt, als würdet ihr beide auf den anderen warten, dass er den ersten Schritt macht.$bp$, $bp$„Wer wartet bei euch gerade auf wen?"$bp$, $bp$der Nutzer in einer Beziehung auf den ersten Schritt des anderen wartet$bp$, '{}'::text[], array[$bp$rueckzug_unter_druck$bp$, $bp$harmonie_um_jeden_preis$bp$]::text[], array[$bp$zirkulaere_kausalitaet$bp$]::text[], array[$bp$Partnerschaft$bp$, $bp$Schweigen$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T3-E$bp$, $bp$erklaerung$bp$, 3, $bp$Die Kampagne$bp$, $bp$erster Frost$bp$, $bp$Was dahintersteckt: Gut gemeint ist nicht gut angekommen$bp$, $bp$Wer ungefragt hilft, legt sein eigenes Wertesystem an das Problem des anderen und verlässt die Augenhöhe. Erwartungen, die keiner kennt. Selbstsabotage als „lieber das bekannte Übel", weil das Bekannte Sicherheit gibt. Kapiert ist nicht gekonnt: Die Autobahn ist der alte Weg, der Trampelpfad der neue.$bp$, $bp$Gut gemeint ist nicht gut angekommen.$bp$, null, null, array[$bp$Woher wusstest du, was er braucht?$bp$, $bp$Wann hast du jemandem zuletzt was zugetraut, statt es für ihn zu erledigen?$bp$]::text[], '{}'::text[], array[$bp$ungefragte_hilfe$bp$, $bp$unausgesprochene_erwartungen$bp$, $bp$bekanntes_uebel$bp$, $bp$autobahn_trampelpfad$bp$]::text[], '{}'::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T3-J$bp$, $bp$jerome$bp$, 3, $bp$Die Kampagne$bp$, $bp$erster Frost$bp$, $bp$Der Retter$bp$, $bp$Jerome war jahrelang der, der alles organisiert und für jeden eine Lösung hat. Dazu kam die stille Buchführung: immer für alle da und insgeheim eine Gegenleistung erwarten, von der niemand weiß.$bp$, $bp$Ich habe mich auch mal als Retter gesehen. Ob einer gerettet werden wollte, hab ich selten gefragt.$bp$, $bp$„Jerome nennt das im Buch ‚stille Buchführung'. Gibt es bei dir auch so eine Rechnung, die keiner kennt?"$bp$, $bp$der Nutzer sich als „der, der immer für alle da ist" beschreibt$bp$, '{}'::text[], array[$bp$uebernahme_reflex$bp$]::text[], array[$bp$unausgesprochene_erwartungen$bp$]::text[], array[$bp$Helfen$bp$, $bp$Enttäuschung$bp$, $bp$Selbstbild$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T4-D1$bp$, $bp$dialog$bp$, 4, $bp$Wo hast du das her?$bp$, $bp$Anfang Dezember$bp$, $bp$Das musst du dir erst mal verdienen$bp$, $bp$Emma (9) wünscht sich ein Handy. Tim hört sich in der Küche einen Satz sagen und erkennt seinen Vater darin. Sein Bruder hat dieselben Sprüche bekommen, und die haben ihn nie gejuckt.$bp$, $bp$Das ist mein Vater. Wortgleich.$bp$, $bp$„Tim hört sich im Buch plötzlich wie sein Vater reden. Wessen Stimme hörst du da gerade?"$bp$, $bp$der Nutzer bei sich einen Satz oder ein Verhalten seiner Eltern bemerkt$bp$, '{}'::text[], '{}'::text[], array[$bp$lernen_am_modell$bp$, $bp$gesagt_ist_nicht_gehoert$bp$]::text[], array[$bp$Eltern$bp$, $bp$Kinder$bp$, $bp$Erziehung$bp$, $bp$Herkunft$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T4-D2$bp$, $bp$dialog$bp$, 4, $bp$Wo hast du das her?$bp$, $bp$Anfang Dezember$bp$, $bp$Was zählt nicht? Ich.$bp$, $bp$Mara fragt (mit ausdrücklicher Erlaubnis) zurück zu dem Neunjährigen, der eine Zwei nach Hause bringt und einen stillen Abend erlebt. Tim formuliert zum ersten Mal seinen Glaubenssatz und merkt, dass ihn so nie jemand ausgesprochen hat.$bp$, $bp$Ich bin nur was wert, wenn ich’s draufhab$bp$, $bp$„Tim hat im Buch einen Satz über sich gefunden, den er für eine Tatsache hielt. Gibt es bei dir so einen Satz?"$bp$, $bp$der Nutzer seinen Wert an Leistung koppelt oder Kritik als Urteil über sich als Mensch erlebt$bp$, '{}'::text[], array[$bp$innerer_kritiker$bp$, $bp$perfektionismus_blockade$bp$]::text[], array[$bp$glaubenssatz$bp$]::text[], array[$bp$Selbstwert$bp$, $bp$Leistung$bp$, $bp$Kindheit$bp$]::text[], $bp$Mara fragt hier erst um Erlaubnis („Aber nur, wenn du da hin willst"). Das gilt auch für den Coach.$bp$, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T4-D3$bp$, $bp$dialog$bp$, 4, $bp$Wo hast du das her?$bp$, $bp$Anfang Dezember$bp$, $bp$Wozu brauchst du ihn heute noch?$bp$, $bp$Tim erkennt, was er von der Tabelle doch hatte: gebraucht zu werden. Mara stellt die Frage nach der heutigen Funktion des Glaubenssatzes, und Tim hat keine Antwort.$bp$, $bp$Und wozu brauchst du ihn heute noch?$bp$, $bp$„Was hast du davon, auch wenn es dich viel kostet?"$bp$, $bp$der Nutzer ein Muster loswerden will, aber nicht sieht, was es ihm gibt$bp$, '{}'::text[], array[$bp$uebernahme_reflex$bp$]::text[], array[$bp$positive_absicht$bp$, $bp$funktion_von_symptomen$bp$]::text[], array[$bp$Selbstwert$bp$, $bp$Gebrauchtwerden$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T4-D4$bp$, $bp$dialog$bp$, 4, $bp$Wo hast du das her?$bp$, $bp$Anfang Dezember$bp$, $bp$Das ist die Tabelle$bp$, $bp$Auf dem Rückweg erzählt Tim, wie er jeden Abend bei Emmas Hausaufgaben sitzt und ihr den Stift abnimmt. Mitten im Satz erkennt er dasselbe Muster wie bei Jule.$bp$, $bp$Das ist die Tabelle$bp$, $bp$„Tim hat sein Muster an einer ganz anderen Stelle wiedergefunden. Wo begegnet dir deins noch?"$bp$, $bp$der Nutzer dasselbe Muster in einem zweiten Lebensbereich wiederfindet$bp$, '{}'::text[], array[$bp$uebernahme_reflex$bp$]::text[], array[$bp$glaubenssatz$bp$, $bp$ungefragte_hilfe$bp$]::text[], array[$bp$Kinder$bp$, $bp$Hausaufgaben$bp$, $bp$Helfen$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T4-E1$bp$, $bp$erklaerung$bp$, 4, $bp$Wo hast du das her?$bp$, $bp$Anfang Dezember$bp$, $bp$Was dahintersteckt: Vom Wert zum Glaubenssatz$bp$, $bp$Kinder lernen durch Hingucken. Adlers Lebensstil. Ein Glaubenssatz ist eine Bedingung, die wir an ein Bedürfnis knüpfen („Ich bin nur was wert, wenn …"). Meistens hat ihn nie jemand ausgesprochen. Ein Glaubenssatz läuft überall mit. Geprägt, nicht defekt. Die Eltern sind nicht schuld.$bp$, $bp$Mit neun konntest du deinen Glaubenssatz nicht prüfen. Heute kannst du’s.$bp$, null, null, array[$bp$Welcher Glaubenssatz bestimmt heute noch mit, wie du dich verhältst?$bp$, $bp$Wie würde jemand, der dich gernhat, deinen Glaubenssatz formulieren?$bp$]::text[], '{}'::text[], array[$bp$glaubenssatz$bp$, $bp$lernen_am_modell$bp$, $bp$beduerfnisse$bp$]::text[], '{}'::text[], $bp$Das Buch warnt hier selbst: „Wenn eine Frage mehr aufmacht, als dir guttut, lass sie liegen." Dieselbe Behutsamkeit gilt für den Coach.$bp$, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T4-E2$bp$, $bp$erklaerung$bp$, 4, $bp$Wo hast du das her?$bp$, $bp$Anfang Dezember$bp$, $bp$Was dahintersteckt: Ermutigen statt loben$bp$, $bp$Mit Adler und Kishimi/Koga: Lob ist auch eine Bewertung von oben. Ermutigung begegnet auf Augenhöhe: „Ich glaub, das kriegst du hin." Oder: „Danke, das hat mir geholfen." Gemeint ist eine Haltung, keine Regel gegen jedes Lob.$bp$, $bp$Wer lobt, beurteilt.$bp$, null, $bp$der Nutzer über Erziehung oder Führung spricht und sich fragt, wie er unterstützen kann, ohne zu bewerten$bp$, '{}'::text[], '{}'::text[], array[$bp$ermutigen_statt_loben$bp$]::text[], array[$bp$Eltern$bp$, $bp$Führung$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T4-E3$bp$, $bp$erklaerung$bp$, 4, $bp$Wo hast du das her?$bp$, $bp$Anfang Dezember$bp$, $bp$Was dahintersteckt: Positive Absicht$bp$, $bp$Hinter fast jedem Verhalten steckt ein guter Grund, meistens ein Bedürfnis. Wer Konflikte vermeidet, will dazugehören. Wer kontrolliert, will Sicherheit. Wer ungefragt hilft, will gebraucht werden. Verstehen heißt nicht hinnehmen und nicht gutheißen.$bp$, $bp$Jedes Verhalten hat einen guten Grund.$bp$, null, $bp$der Nutzer sich für ein Verhalten fertigmacht oder einen anderen Menschen nicht versteht$bp$, '{}'::text[], '{}'::text[], array[$bp$positive_absicht$bp$, $bp$funktion_von_symptomen$bp$, $bp$beduerfnisse$bp$]::text[], '{}'::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T4-J1$bp$, $bp$jerome$bp$, 4, $bp$Wo hast du das her?$bp$, $bp$Anfang Dezember$bp$, $bp$Drei Glaubenssätze, eine Frage$bp$, $bp$Jerome schaut zwei Generationen zurück: die Oma, die sich nirgends willkommen fühlte und nur da sein durfte, wenn sie nützlich war. Er selbst als Kind, das „die Welt retten" wollte und große Antennen für jede schlechte Stimmung hatte.$bp$, $bp$Was muss ich tun, damit ich hier sein darf?$bp$, null, $bp$der Nutzer selbst über Familienmuster über Generationen spricht$bp$, '{}'::text[], array[$bp$uebernahme_reflex$bp$]::text[], array[$bp$glaubenssatz$bp$, $bp$lernen_am_modell$bp$]::text[], array[$bp$Familie$bp$, $bp$Herkunft$bp$, $bp$Zugehörigkeit$bp$]::text[], null, false, true, $bp$Keine Details zu Oma, Stiefmutter oder Nazizeit. Nur die Kernaussage: Glaubenssätze werden weitergegeben. Der Kernsatz enthält „muss". Das ist als Zitat des alten Glaubenssatzes erlaubt, der Coach formuliert drumherum ohne „müssen".$bp$, true, '2026-11-21'::timestamptz),
  ($bp$T4-J2$bp$, $bp$jerome$bp$, 4, $bp$Wo hast du das her?$bp$, $bp$Anfang Dezember$bp$, $bp$Die Zündschnur$bp$, $bp$Jerome erzählt offen, dass er, überfordert von vier Kindern, manchmal brüllt und auf den Tisch haut, sich danach entschuldigt, und dass seine Kinder sich etwas von ihm abgucken.$bp$, $bp$Eins weiß ich. Sie gucken sich was ab.$bp$, null, $bp$der Nutzer sich als Elternteil für eigene Ausbrüche schämt$bp$, '{}'::text[], '{}'::text[], array[$bp$lernen_am_modell$bp$]::text[], array[$bp$Eltern$bp$, $bp$Überforderung$bp$, $bp$Wut$bp$]::text[], null, false, true, $bp$Nur als Entlastung („Auch Jerome erzählt im Buch, dass ihm das passiert"), nie als Rechtfertigung. Keine Details.$bp$, true, '2026-11-21'::timestamptz),
  ($bp$T5-D1$bp$, $bp$dialog$bp$, 5, $bp$Seh ich anders$bp$, $bp$Januar$bp$, $bp$Das ist einfach falsch$bp$, $bp$An Silvester nimmt Tim Emma vor allen das Handy von Bastis Sohn weg, Basti nennt ihn spießig. Tim lacht mit und ruft zwei Tage später an, um Basti zu sagen, dass er es falsch macht. Basti legt auf.$bp$, $bp$Ich hab doch nur die Wahrheit gesagt.$bp$, $bp$„Tim hat das im Buch auch gesagt, ‚Ich hab doch nur die Wahrheit gesagt'. Was könnte bei dem anderen angekommen sein?"$bp$, $bp$der Nutzer überzeugt ist, „einfach nur die Wahrheit" gesagt zu haben, und der andere sich abwendet$bp$, '{}'::text[], array[$bp$harmonie_um_jeden_preis$bp$]::text[], array[$bp$normal_ist_nicht_wahrheit$bp$, $bp$gesagt_ist_nicht_gehoert$bp$]::text[], array[$bp$Freundschaft$bp$, $bp$Erziehung$bp$, $bp$Streit$bp$]::text[], null, false, false, null, true, '2026-11-21'::timestamptz),
  ($bp$T5-D2$bp$, $bp$dialog$bp$, 5, $bp$Seh ich anders$bp$, $bp$Januar$bp$, $bp$Mara und Ines$bp$, $bp$Mara erzählt von ihrer Schwester. Als die Mutter dement wurde, wollte Ines sie ins Heim geben, und Mara hat jahrelang gesagt: Das ist falsch. Seit der Beerdigung reden die beiden nicht mehr.$bp$, $bp$Ich war mir so sicher. Das war jahrelang mein Lieblingssatz.$bp$, null, $bp$der Nutzer mit einem Angehörigen wegen einer Überzeugung gebrochen hat$bp$, '{}'::text[], '{}'::text[], array[$bp$normal_ist_nicht_wahrheit$bp$]::text[], array[$bp$Geschwister$bp$, $bp$Pflege$bp$, $bp$Bruch$bp$]::text[], null, false, true, $bp$Pflege, Demenz und Heim sind belastend. Nur wenn der Nutzer es selbst anspricht. Die Botschaft: Auch Mara, die nur Fragen stellt, ist nicht frei davon.$bp$, true, '2026-11-21'::timestamptz),
  ($bp$T5-D3$bp$, $bp$dialog$bp$, 5, $bp$Seh ich anders$bp$, $bp$Januar$bp$, $bp$Hast du ’n Kurs gemacht, oder was?$bp$, $bp$Tim ruft Basti mit einem vorbereiteten Zettel an, beide lachen sich kaputt. Dann erzählt Basti, warum Jonas ein Handy hat: Busfahrten allein, Ortung, Steffi hat Spätschicht. Tim hatte nie gefragt.$bp$, $bp$Ich dachte die ganze Zeit, er hat angefangen.$bp$, $bp$„Was weißt du eigentlich über seine Gründe?"$bp$, $bp$der Nutzer die Gründe des anderen nicht kennt und nie gefragt hat$bp$, '{}'::text[], '{}'::text[], array[$bp$beduerfnisse_gleich_wege_verschieden$bp$, $bp$zirkulaere_kausalitaet$bp$, $bp$seh_ich_anders$bp$]::text[], array[$bp$Freundschaft$bp$, $bp$Versöhnung$bp$]::text[], $bp$Der Satz „Hast du ’n Kurs gemacht, oder was?" ist ein Running Gag (Teil 5 und 6). Für Leser ein liebevoller Wiedererkennungsmoment, aber nicht als Spott einsetzen.$bp$, false, false, null, true, '2026-11-21'::timestamptz),
